<?php
// Include your existing working helper that uses the FCM HTTP v1 API
include('../include/notifications.php');

// Put a valid Android FCM Token here. 
// Note: Tokens are usually long strings generated by FirebaseMessaging.getInstance().getToken() on the Android device.
$token = "YOUR_VALID_ANDROID_FCM_TOKEN_HERE";

$title = "Test Notification";
$body  = "This is a test message from PHP using HTTP v1";

echo "Sending notification...<br>";

// sendFCMNotification() handles all the OAuth token generation and sends via v1 API
$response = sendFCMNotification($token, $title, $body);

echo "Firebase Response: <br>"; 
echo $response;
?>